{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 10,
      "verse": 21,
      "text_ar": "فإنكم ترون أن مقدسنَا قد أُخرب، ومذبحنَا هُدم، وهيكلَنَا دُمِّر،",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 22,
      "text_ar": "وعودُنَا وُضع في الحضيض، وأُسكت نشيدُنَا، وانتهى ابتهاجُنَا، وأُطفئ نورُ سراجِنَا، ونُهب تابوتُ عهدِنَا، ودُنست مقدساتُنَا، ودُنِّس الاسمُ الذي نُدعى به. وعُامل أحرارُنَا باحتقار، وأُحرق كهنتُنَا، وذهب لاويُونَا إلى السبي، ودُنست عذاراُنَا واغتُصبت نساؤُنَا، وسيق أبرارُنَا، وغُدر بأطفالُنَا، وأُدخل شبابُنَا في العبودية، وصار أقوياؤُنَا ضعفاء.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 23,
      "text_ar": "وما هو أعظم من ذلك كلِّه، فإن ختم صهيون قد فقد الآن ختم كرامتها، وسُلّمت إلى أيدي مبغضينا.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 24,
      "text_ar": "لذلك انفضوا عنكم الحزن العظيم، واطرحوا عن أنفسكم كثرة الأحزان، لكي يرحمكم القدير مرة أخرى، ويهبكم العلي راحة، بل دعة من ضيقاتكم».",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 25,
      "text_ar": "وحدث بينما كنت أتكلم معها، هوذا وجهها بدأ فجأة يضيء جداً، وبرق محياها كالبرق، حتى خفتُ منها جداً، وتعجبت ما عسى أن يكون هذا.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 26,
      "text_ar": "وهوذا فجأة أطلقت صرخة عظيمة ومخيفة جداً، حتى اهتزت الأرض للصوت.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 27,
      "text_ar": "فنظرتُ، وإذا بالمرأة لا تظهر لي بعد، بل كانت هناك مدينة مبنية، ومكان قد ظهر له أساسات واسعة. فحينئذ خفتُ، وصرخت بصوت عظيم،",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 28,
      "text_ar": "«أين أوريئيل الملاك الذي جاء إليّ في البدء؟ لأنه جعلني أقع في هذه الغيبوبة العظيمة، وقد تحولت نهايتي إلى فساد، وصلاتي إلى عار!»",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 29,
      "text_ar": "وبينما كنت أتكلم بهذا الكلام، هوذا الملاك الذي أتى إليّ في البدء قد أتى إليّ، ونظر إليّ.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 30,
      "text_ar": "وهوذا كنت مضطجعاً كالميت، ونُزعت مني فِطنتي. فأمسكني بيدي اليمنى، وعزاني، وأقامني على قدميَّ، وقال لي:",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 31,
      "text_ar": "«ما بك؟ ولماذا أنت مضطرب هكذا؟ ولماذا اضطربت فِطنتك وأفكار قلبك؟»",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 32,
      "text_ar": "فقلت: «لأنك تركتني؛ ومع ذلك فقد فعلت حسب أقوالك، وذهبت إلى الحقل، وها أنا قد رأيت، ولا أزال أرى، ما لا أستطيع أن أفسره».",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 33,
      "text_ar": "فقال لي: «اصمد كالرجل، وسأعلمك».",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 34,
      "text_ar": "فقلت: «تكلم يا سيدي؛ فقط لا تتركني، لئلا أموت قبل أواني.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 35,
      "text_ar": "فإني قد رأيت ما لم أكن أعرفه، وأسمع ما لا أعرفه.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 36,
      "text_ar": "أم أن حواسي مخدوعة، أم أن نفسي في حُلم؟",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 37,
      "text_ar": "فالآن إذن أرجوك أن تفسر لعبدك معنى هذه الرؤيا».",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 38,
      "text_ar": "فأجابني قائلاً: «اسمع لي، وسأعلمك، وأخبرك بالأمور التي تخاف منها، لأن العلي قد كشف لك أسراراً كثيرة.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 39,
      "text_ar": "فقد رأى أن طريقك بارّ، لأنك تحزن دائماً من أجل شعبك، وتنوح مناحة عظيمة على صهيون.",
      "review_notes_ar": []
    },
    {
      "chapter": 10,
      "verse": 40,
      "text_ar": "فهذا إذن هو معنى الرؤيا.",
      "review_notes_ar": []
    }
  ]
}
